export const ADDRESS: Record<DreamKey, 'feminine' | 'masculine' | 'neutral'> = { sealed1: 'neutral', sealed2: 'feminine', sealed3: 'feminine', acc1: 'feminine', acc2: 'masculine', acc3: 'neutral' };

/** The whole dream allowed and every answer: the golden set checks sentences, not which moment they belong to. */
export const sourcesOf = (k: DreamKey) => {
  const segments = segmentDream(DREAM[k]);
  return { language: 'he' as const, sourceText: DREAM[k], segments, allowed: segments.map((s) => s.id), answers: ANSWERS[k], address: ADDRESS[k] };
};

export type Relation = 'contrast' | 'repeat' | 'similar' | 'want-vs-cannot' | 'change' | 'missing' | 'odd' | 'echo' | 'side-by-side' | 'open-link';
export interface Anchor {
  quote: string;
  from: 'dream' | 'answer';
}
export interface Card {
  anchors: Anchor[];
  relation: Relation;
  basis: string[];
  aboutHer: { claim: string; quote: string }[];
  openEdge: string;
}
export interface Example {
  id: string;
  dream: DreamKey;
  text: string;
  card?: Card;
  /** The level doc 50 v2 gives it (0–3); for the bad ones, what must happen. */
  level?: 0 | 1 | 2 | 3;
  /** The question she was asked in the run, with her answer (an echo joins them again). */
  exchange?: { question: string; answer: string };
}

